fn is_odd_at_odd_index(arr: &Vec<usize>) -> bool {
    for (i, &val) in arr.iter().enumerate() {
        // i % 2 == 0 means even index, so val % 2 must be 0 (even)
        // i % 2 == 1 means odd index, so val % 2 must be 1 (odd)
        if (i % 2) != (val % 2) {
            return false;
        }
    }
    true
}

